"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["57734"],{77540(e){e.exports=JSON.parse('{"id":"F510","slug":"ppe-rollforward","name":"PP&E Roll-Forward","subject":"Accounting Mastery & Financial Modeling","section":"Financial statement mechanics","topic":"Financial statement mechanics","level":"Beginner","aliases":["fixed asset schedule","capex from balance sheets","supporting schedule"],"formula":{"latex":"PPE_{end}=PPE_{begin}+\\\\text{CapEx}-\\\\text{Depreciation}-\\\\text{Disposals}","also":[],"text":"Ending PP&E = Opening PP&E + Capex - Depreciation - Net book value of disposals; so Capex = Ending - Opening + Depreciation + Disposals"},"symbols":[{"symbol":"PPE","meaning":"Net property, plant and equipment on the balance sheet","unit":"money"},{"symbol":"CapEx","meaning":"Capital expenditure for the year","unit":"money"},{"symbol":"Depreciation","meaning":"Depreciation charge for the year","unit":"money"},{"symbol":"Disposals","meaning":"Net book value of assets sold or scrapped","unit":"money"}],"when_to_use":"Use it to build a forecast, with capex and depreciation as drivers, or to work out capex from two balance sheets when the cash flow statement is not available. A roll-forward ties each balance to the flows that changed it, and is the base of every supporting schedule in a model.","worked_example":{"problem":"Opening PP&E is 1,000. The company spent 110 on capex, charged 90 of depreciation and disposed of assets with a net book value of 10. Separately, another company shows opening PP&E of 800 and closing PP&E of 860, depreciation of 70 and no disposals.","inputs":{"open":1000,"capex":110,"dep":90,"disp":10,"o2":800,"c2":860,"d2":70},"steps":[{"label":"Closing PP&E = opening + capex - depreciation - disposals","working":"1000+110-90-10","value":"1,010.00"},{"label":"Implied capex = closing - opening + depreciation","working":"860-800+70","value":"130.00"}],"answer":"Closing PP&E is 1,010.00. For the second company, capex can be worked out as 130.00: closing minus opening plus depreciation."},"calculator":{"available":true,"inputs":[{"id":"open","label":"Opening PP&E","unit":"money","type":"number","default":1000,"hint":""},{"id":"capex","label":"Capex","unit":"money","type":"number","default":110,"hint":""},{"id":"dep","label":"Depreciation","unit":"money","type":"number","default":90,"hint":""},{"id":"disp","label":"Disposals at net book value","unit":"money","type":"number","default":10,"hint":""},{"id":"o2","label":"Second company: opening PP&E","unit":"money","type":"number","default":800,"hint":""},{"id":"c2","label":"Second company: closing PP&E","unit":"money","type":"number","default":860,"hint":""},{"id":"d2","label":"Second company: depreciation","unit":"money","type":"number","default":70,"hint":""}],"checks":[],"steps":[{"id":"end","label":"Closing PP&E = opening + capex - depreciation - disposals","expr":"open+capex-dep-disp","format":"money"},{"id":"capex2","label":"Implied capex = closing - opening + depreciation","expr":"c2-o2+d2","format":"money"}],"results":["end","capex2"],"percent_inputs_typed_as_whole_numbers":true,"tested_against":{"end":1010,"capex2":130}},"finder":{"finds":"Closing PP&E, or the capex implied by two balance sheets","needs":"Opening and closing balances, depreciation, disposals"},"related":[{"slug":"cash-flow-statement-link","name":"Linking the Three Statements: Cash Flow and Balance Check"},{"slug":"net-book-value","name":"Net Book Value"},{"slug":"straight-line-depreciation","name":"Straight-Line Depreciation"}],"related_ids":["F509","F072","F073"],"group":"Companies and valuation","mathml":"<span class=\\"katex\\"><math xmlns=\\"http://www.w3.org/1998/Math/MathML\\" display=\\"block\\"><semantics><mrow><mi>P</mi><mi>P</mi><msub><mi>E</mi><mrow><mi>e</mi><mi>n</mi><mi>d</mi></mrow></msub><mo>=</mo><mi>P</mi><mi>P</mi><msub><mi>E</mi><mrow><mi>b</mi><mi>e</mi><mi>g</mi><mi>i</mi><mi>n</mi></mrow></msub><mo>+</mo><mtext>CapEx</mtext><mo>\u2212</mo><mtext>Depreciation</mtext><mo>\u2212</mo><mtext>Disposals</mtext></mrow><annotation encoding=\\"application/x-tex\\">PPE_{end}=PPE_{begin}+\\\\text{CapEx}-\\\\text{Depreciation}-\\\\text{Disposals}</annotation></semantics></math></span>","alsoMathml":[],"prev":{"slug":"position-size-stop-loss","name":"Position Size from a Stop-Loss"},"next":{"slug":"vc-post-money","name":"Pre-Money and Post-Money Valuation"},"lesson":null,"total":522}')}}]);